def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'
    if n == 2:
        return 'C' if history[1][1] == 'C' else 'D'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    total_opp_c = opp.count('C')
    total_opp_d = n - total_opp_c
    total_my_c = my.count('C')
    total_my_d = n - total_my_c

    # Early game: simple TFT
    if n < 10:
        return 'C' if opp[-1] == 'C' else 'D'

    # Persistent defector
    if total_opp_d > n * 0.8:
        return 'D'

    # Probe at n=10 if no defections yet
    if n == 10 and total_opp_d == 0:
        return 'D'
    if n == 11:
        return 'C'

    retaliated = (opp[11] == 'D') if n > 11 else False

    # Retaliated probe -> TFT-like
    if retaliated:
        if total_opp_d > n * 0.4:
            return 'D'
        if n == 99:
            return 'D'
        return 'C'

    # TFT-like correlation
    if n >= 10:
        matches = sum(1 for i in range(1, n) if opp[i] == my[i-1])
        if matches >= (n - 1) * 0.7:
            if n == 99:
                return 'D'
            return 'C'

    # If opponent is defecting too much, punish
    if total_opp_d > n * 0.3:
        return 'D'

    # Exploitative mode
    if n >= 90:
        return 'D'
    recent_my = my[-10:]
    recent_my_d = recent_my.count('D')
    if recent_my_d >= 5:
        return 'C'
    if total_my_c - total_my_d < 5:
        return 'C'
    if opp[-1] == 'D':
        return 'C'
    return 'D'
